script:
frappe.ui.form.on("Sales Invoice", {
	onload(frm) {
		// Pre-tick "Update Stock" on a brand-new Sales Invoice typed on the desk
		// form. Runs once, on load of a new form only; saved invoices are never
		// touched and the user stays free to untick it.
		//
		// Matches actual practice: every non-POS, non-return invoice since
		// Mar 2026 was saved with Update Stock ticked.
		if (!frm.is_new()) return;

		// 1. Returns / credit notes mirror the invoice they came from — some
		//    legitimately carry Update Stock = 0, so never force them to 1.
		if (frm.doc.is_return) return;

		// 2. Amended documents inherit the original's value; leave it alone.
		if (frm.doc.amended_from) return;

		// 3. POS invoices: the server overwrites update_stock from the POS
		//    Profile (sales_invoice.py set_pos_fields), so don't fight it.
		if (frm.doc.is_pos) return;

		// 4. Invoices raised from a Delivery Note: the stock already left on the
		//    note. ERPNext rejects Update Stock here, and depends_on hides the
		//    checkbox, so a forced tick would be an error nobody can clear.
		const from_delivery_note = (frm.doc.items || []).some(
			(i) => i.dn_detail || i.delivery_note
		);
		if (from_delivery_note) return;

		if (!frm.doc.update_stock) {
			frm.set_value("update_stock", 1);
		}
	},

	refresh(frm) {
		// Safety net for "Get Items From > Delivery Note" on a draft that
		// already has Update Stock ticked. Only ever turns the flag OFF — in a
		// state ERPNext would refuse to save anyway — and says why.
		if (frm.doc.docstatus !== 0 || !frm.doc.update_stock) return;

		const from_delivery_note = (frm.doc.items || []).some(
			(i) => i.dn_detail || i.delivery_note
		);
		if (from_delivery_note) {
			frm.set_value("update_stock", 0);
			frappe.show_alert(
				{
					message: __(
						"Update Stock turned off — this stock has already left on the Delivery Note."
					),
					indicator: "orange",
				},
				7
			);
		}
	},
});
